Here is the commit message:
llext: fix llext_load() optimization

The optimization in llext_load() to avoid using the generic path for
sections that are cached in memory was broken for two reasons:
- it was comparing an ELF section index to LLEXT_MEM_BSS, which is a
  llext_mem enum, and
- it was using the wrong section address for the cached sections since
  the "merged sections" feature was introduced in 709b2e44bfd.

This patch fixes both issues using the new llext_loaded_sect_ptr()
helper function.

Signed-off-by: Luca Burelli <l.burelli@arduino.cc>

Here is the root cause:
The bug was caused by an incorrect comparison of an ELF section index to `LLEXT_MEM_BSS`, which is an enum specific to memory types, rather than properly handling section indices. Additionally, the section address for cached sections was incorrectly retrieved due to changes introduced by the "merged sections" feature, leading to the use of outdated logic that did not account for the new structure of section management.

Here is the patch:

 static int llext_copy_symbols(struct llext_loader *ldr, struct llext *ext,
 			      bool pre_located)
 {
 	size_t ent_size = ldr->sects[LLEXT_MEM_SYMTAB].sh_entsize;
 	size_t syms_size = ldr->sects[LLEXT_MEM_SYMTAB].sh_size;
 	int sym_cnt = syms_size / sizeof(elf_sym_t);
 	struct llext_symtable *sym_tab = &ext->sym_tab;
 	elf_sym_t sym;
 	int i, j, ret;
 	size_t pos;

 	for (i = 0, pos = ldr->sects[LLEXT_MEM_SYMTAB].sh_offset, j = 0;
 	     i < sym_cnt;
 	     i++, pos += ent_size) {
 		if (!i) {
 			/* A dummy entry */
 			continue;
 		}

 		ret = llext_seek(ldr, pos);
 		if (ret != 0) {
 			return ret;
 		}

 		ret = llext_read(ldr, &sym, ent_size);
 		if (ret != 0) {
 			return ret;
 		}

 		uint32_t stt = ELF_ST_TYPE(sym.st_info);
 		uint32_t stb = ELF_ST_BIND(sym.st_info);
 		unsigned int sect = sym.st_shndx;

 		if ((stt == STT_FUNC || stt == STT_OBJECT) &&
 		    stb == STB_GLOBAL && sect != SHN_UNDEF) {
 			const char *name = llext_string(ldr, ext, LLEXT_MEM_STRTAB, sym.st_name);

 			__ASSERT(j <= sym_tab->sym_cnt, "Miscalculated symbol number %u\n", j);

 			sym_tab->syms[j].name = name;

-			uintptr_t section_addr;
-			void *base;
-
-			if (sect < LLEXT_MEM_BSS) {
-				/*
-				 * This is just a slight optimisation for cached
-				 * sections, we could use the generic path below
-				 * for all of them
+			elf_shdr_t *shdr = ldr->sect_hdrs + sect;
+			uintptr_t section_addr = shdr->sh_addr;
+			const void *base;
+
+			base = llext_loaded_sect_ptr(ldr, ext, sect);
+			if (!base) {
+				/* If the section is not mapped, try to peek.
+				 * Be noisy about it, since this is addressing
+				 * data that was missed by llext_map_sections.
 				 */
-				base = ext->mem[ldr->sect_map[sect].mem_idx];
-				section_addr = ldr->sects[ldr->sect_map[sect].mem_idx].sh_addr;
-			} else {
-				elf_shdr_t *shdr = ldr->sect_hdrs + sect;
-
 				base = llext_peek(ldr, shdr->sh_offset);
-				if (!base) {
-					LOG_ERR("cannot handle arbitrary sections without .peek\n");
+				if (base) {
+					LOG_DBG("section %d peeked at %p", sect, base);
+				} else {
+					LOG_ERR("No data for section %d", sect);
 					return -EOPNOTSUPP;
 				}
-
-				section_addr = shdr->sh_addr;
 			}

 			if (pre_located) {
 				sym_tab->syms[j].addr = (uint8_t *)sym.st_value +
 					(ldr->hdr.e_type == ET_REL ? section_addr : 0);
 			} else {
 				sym_tab->syms[j].addr = (uint8_t *)base + sym.st_value -
 					(ldr->hdr.e_type == ET_REL ? 0 : section_addr);
 			}

 			LOG_DBG("function symbol %d name %s addr %p",
 				j, name, sym_tab->syms[j].addr);
 			j++;
 		}
 	}

 	return 0;
 }



